  const baseText = new Map();
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node;
  while (node = walker.nextNode()) {
    if (node.nodeValue.trim()) baseText.set(node, node.nodeValue);
  }

  function apply(lang){
    const dict = T[lang] || T.no;
    document.documentElement.lang = lang;
    document.title = lang === 'no' ? 'Tango Sørlandet – mer tango på Sørlandet' : lang === 'en' ? 'Tango Sørlandet – more tango in Southern Norway' : 'Tango Sørlandet – más tango en el sur de Noruega';
    baseText.forEach((original, textNode) => {
      if (dict[original] !== undefined) textNode.nodeValue = dict[original];
    });
    document.querySelectorAll('.lang-btn').forEach(b => b.classList.toggle('active', b.dataset.lang === lang));
    localStorage.setItem('tangoSorlandet_language', lang);
  }

  document.querySelectorAll('.lang-btn').forEach(b => b.addEventListener('click', () => apply(b.dataset.lang)));
  apply(localStorage.getItem('tangoSorlandet_language') || 'no');
